LAB.add({},{'Climb, cruise and fuel planning':'Stigning, marsj og drivstoffplanlegging','Birdbird Virtual Lab · Performance':'Birdbird Virtual Lab · Ytelse',
 '1 · Understand':'1 · Forstå','2 · Explore':'2 · Utforsk','3 · Test yourself':'3 · Test deg selv','Key concepts':'Nøkkelbegreper','Deep dive':'Dypdykk','The climb, cruise and fuel lab':'Stigning-, marsj- og drivstofflabben','Try it':'Prøv selv','Key points':'Det viktigste','Test yourself':'Test deg selv',
 'Controls':'Kontroller','Aircraft':'Fly','Flight':'Flyging','The flight':'Flygingen','More fuel':'Mer drivstoff','Scenarios':'Scenarier','Advanced':'Avansert','Rules':'Regler','Destination alternate':'Destinasjonsalternativ','Contingency':'Uforutsett','Mode':'Modus','Sections':'Seksjoner',
 'Drag and thrust against airspeed with the best climb speeds; fuel flow against airspeed with the best range and endurance speeds; and the fuel for a flight as a stack against the tank.':'Motstand og skyvekraft mot fart med de beste stigefartene; drivstofforbruk mot fart med fartene for beste rekkevidde og flytid; og drivstoffet for en flytur som en stabel mot tanken.'});
LAB.tx({lead:'Hvilken fart stiger brattest, hvilken stiger raskest, og hvilken kommer lengst på en tank drivstoff? Svarene er forskjellige for propell og jet, og vinden flytter dem. Bygg så drivstoffet for en flytur slik reglene krever, del for del, fra taxe til endelig reserve.'});
function texts(){
  el('kin').textContent=L(t2('Six ideas carry climb, cruise and fuel. “Show in the model” sets the lab up so you can see it.','Seks ideer bærer stigning, marsj og drivstoff. «Vis i modellen» setter opp labben så du kan se det.'));
  el('xLead').textContent=L(t2('Pick the aircraft and a mode. In Climb and Cruise the curve is the idea: where the lines are furthest apart, or where a straight line from the origin just touches the curve. In Fuel, build the plan part by part.','Velg fly og modus. I Stigning og Marsj er kurven selve ideen: der linjene er lengst fra hverandre, eller der en rett linje fra origo så vidt berører kurven. I Drivstoff bygger du planen del for del.'));
  el('tryLead').textContent=L(t2('Work it out first, then check. "Check it in the model" shows you why.','Regn det ut først, og sjekk. «Sjekk i modellen» viser deg hvorfor.'));
  el('foot').innerHTML=L(t2('<b>Model and limitations.</b> Teaching model, not for flight or flight planning. Three generic aircraft with typical, rounded values (light single ≈ 1 100 kg, turboprop twin ≈ 21 t, jet twin ≈ 66 t); none are AFM, FCOM or flight-planning-system data. Parabolic drag polar with a simple wave-drag rise for the jet, ISA, thrust from power for propellers and nearly speed-independent thrust for the jet, constant BSFC/TSFC. Trip fuel is cruise fuel flow × time plus a fixed climb allowance; holding fuel flows are fixed per type. The fuel rules follow the EASA basic fuel scheme (Reg. (EU) 2021/1296, CAT.OP.MPA.181 and AMC1) and Part-NCO (NCO.OP.125) in simplified form; the operator’s approved fuel scheme and the current regulations always apply.','<b>Modell og begrensninger.</b> Undervisningsmodell, ikke for flyging eller flyplanlegging. Tre generiske fly med typiske, avrundede verdier (lett enmotors ≈ 1 100 kg, turboprop tomotors ≈ 21 t, jet tomotors ≈ 66 t); ingen er AFM-, FCOM- eller flyplanleggingsdata. Parabolsk motstandspolar med en enkel bølgemotstand for jet, ISA, skyvekraft fra effekt for propell og nesten fartsuavhengig skyvekraft for jet, konstant BSFC/TSFC. Turdrivstoff er marsjforbruk × tid pluss et fast stigetillegg; forbruket i venting er fast per type. Drivstoffreglene følger EASAs grunnordning (forordning (EU) 2021/1296, CAT.OP.MPA.181 og AMC1) og Part-NCO (NCO.OP.125) i forenklet form; operatørens godkjente drivstoffordning og gjeldende regelverk gjelder alltid.'));
  el('ddH').textContent=L(t2('Deep dive','Dypdykk')); }
function all(){ texts(); drawTabs(); drawPre(); drawTask(); drawDD(); drawTake(); upd(); }
LAB.onLang(all);
document.addEventListener('labdepth',all);
